Body:
The Windows cross-drive check and relative path validation logic are duplicated between the try and catch blocks. Consider extracting this into a helper function to reduce duplication and improve maintainability. For example:

```
function isContained(rel: string): boolean {
  if (process.platform === "win32" && /^[A-Za-z]:/.test(rel)) {
    return false
  }
  return !rel.startsWith("..")
}
```

Then use `return isContained(rel)` in both blocks.

The fallback logic has a potential security weakness: if either parent or child fails to resolve (causing the catch block to execute), the lexical check uses both unresolved paths. This means if the child path contains an unresolved symlink (e.g., because only the parent path failed to resolve), the symlink escape could go undetected.

Consider making the fallback behavior more conservative:
1. Try to resolve each path individually and handle failures separately, or
2. Only fall back to lexical checking when BOTH paths fail to resolve, or  
3. Document why the current behavior is acceptable (e.g., if Instance.directory is always guaranteed to exist and be resolvable)

For example, if parent resolves but child doesn't exist yet, you could still use the resolved parent: `relative(realpathSync(parent), child)` would be safer than `relative(parent, child)`.
```suggestion
    // Try to resolve each path individually to prevent symlink escapes.
    // Fall back to a lexical check only if both resolutions fail.
    let resolvedParent = parent
    let resolvedChild = child
    let parentResolved = false
    let childResolved = false

    try {
      resolvedParent = realpathSync(parent)
      parentResolved = true
    } catch {
      // If the parent doesn't resolve (e.g., directory doesn't exist yet),
      // keep using the original parent path.
    }

    try {
      resolvedChild = realpathSync(child)
      childResolved = true
    } catch {
      // If the child doesn't resolve (e.g., file doesn't exist yet),
      // keep using the original child path.
    }

    // If at least one path resolved, use the best available real paths.
    if (parentResolved || childResolved) {
      const rel = relative(resolvedParent, resolvedChild)
      // On Windows, check for cross-drive paths (e.g., "D:\\..." from "C:\\...")
      if (process.platform === "win32" && /^[A-Za-z]:/.test(rel)) {
        return false
      }
      return !rel.startsWith("..")
    }

    // If realpath fails for both (e.g., neither exists yet), fall back to lexical check.
    const rel = relative(parent, child)
    if (process.platform === "win32" && /^[A-Za-z]:/.test(rel)) {
      return false
    }
    return !rel.startsWith("..")
```

Minor style note: This uses a `let` statement which the style guide recommends avoiding. One alternative would be to calculate the effective MIME type inline:

```typescript
const effectiveMime = (() => {
  const base64Match = url.match(/^data:([^;]+);base64,(.*)$/)
  return base64Match?.[1] || part.mime || "application/octet-stream"
})()
```

However, the current approach is readable and the reassignment is simple enough. Feel free to keep as-is if you prefer the clarity.

Minor suggestion: The `continue` inside the `if (result === "compact")` block is redundant since execution will reach the outer `continue` anyway. Consider removing it for cleaner flow:

```suggestion
      if (result === "compact") {
        await SessionCompaction.create({
          sessionID,
          agent: lastUser.agent,
          model: lastUser.model,
          auto: true,
        })
      }
```

That said, leaving the explicit `continue` could be seen as making intent clearer - your call!

The fallback logic for RUST_TARGET assumes `x86_64-unknown-linux-gnu` for any non-Windows, non-Darwin platform. This means that less common platforms (like FreeBSD, OpenBSD, or other Unix-like systems) would be incorrectly mapped to Linux. Additionally, the logic doesn't account for 32-bit platforms or other architectures like RISC-V or PowerPC.

While these platforms may not be officially supported based on the SIDECAR_BINARIES configuration, the fallback could silently produce an incorrect target that fails later, rather than failing fast with a clear error message.

Consider either adding validation that the computed target is actually in SIDECAR_BINARIES, or documenting that this fallback is intentionally limited to the supported platforms.
```suggestion
function resolveRustTarget(): string {
  const envTarget = Bun.env.RUST_TARGET || Bun.env.TAURI_ENV_TARGET_TRIPLE

  let candidate: string

  if (envTarget) {
    candidate = envTarget
  } else {
    if (process.platform === "win32") {
      candidate = "x86_64-pc-windows-msvc"
    } else if (process.platform === "darwin") {
      candidate = process.arch === "arm64" ? "aarch64-apple-darwin" : "x86_64-apple-darwin"
    } else if (process.platform === "linux") {
      candidate = process.arch === "arm64" ? "aarch64-unknown-linux-gnu" : "x86_64-unknown-linux-gnu"
    } else {
      throw new Error(
        `Unsupported platform '${process.platform}' with architecture '${process.arch}'. ` +
          `Supported Rust targets: ${SIDECAR_BINARIES.map((b) => b.rustTarget).join(", ")}`
      )
    }
  }

  const isSupported = SIDECAR_BINARIES.some((b) => b.rustTarget === candidate)
  if (!isSupported) {
    throw new Error(
      `Unsupported Rust target '${candidate}'. Supported Rust targets: ${SIDECAR_BINARIES.map((b) => b.rustTarget).join(", ")}`
    )
  }

  return candidate
}

export const RUST_TARGET = resolveRustTarget()
```

The platform detection for determining the PTY library differs between the runtime code and the build scripts. In `packages/opencode/src/pty/index.ts` lines 21-29, the code uses `process.platform === "linux"` followed by `process.arch === "arm64"` checks. However, in this build script, the logic checks `item.os === "linux"` then `item.arch === "arm64"`.

While these checks are logically equivalent in their respective contexts, the inconsistency in pattern could lead to maintenance issues. The runtime code checks platform first, then architecture within each platform branch. Consider using a consistent pattern across all files where PTY library selection occurs for better maintainability.
```suggestion
  let ptyLib: string
  if (item.os === "win32") {
    ptyLib = "rust_pty.dll"
  } else if (item.os === "linux") {
    if (item.arch === "arm64") {
      ptyLib = "librust_pty_arm64.so"
    } else {
      ptyLib = "librust_pty.so"
    }
  } else {
    if (item.arch === "arm64") {
      ptyLib = "librust_pty_arm64.dylib"
    } else {
      ptyLib = "librust_pty.dylib"
    }
  }
```

The platform detection logic has a potential issue with future ARM64 Windows support. The code checks `isArm64 = target.startsWith("aarch64")` and then uses this in nested ternaries, but if an ARM64 Windows target (e.g., "aarch64-pc-windows-msvc") is added in the future, the logic would select the wrong PTY library.

The current logic would select "rust_pty.dll" correctly (because `isWindows` is checked first), but the pattern is fragile. The nested ternary structure makes it unclear what would happen for an ARM64 Windows target.

Consider restructuring this to be more explicit, such as checking for specific target combinations or using a switch statement for clarity and future maintainability.
```suggestion
  const isMac = target.includes("apple-darwin")

  let ptyLib: string
  if (isWindows) {
    // Any Windows target (including potential ARM64) uses the .dll
    ptyLib = "rust_pty.dll"
  } else if (isLinux && isArm64) {
    ptyLib = "librust_pty_arm64.so"
  } else if (isLinux) {
    ptyLib = "librust_pty.so"
  } else if (isMac && isArm64) {
    ptyLib = "librust_pty_arm64.dylib"
  } else {
    // Default to the non‑ARM64 macOS dylib (or any other non‑Linux, non‑Windows target)
    ptyLib = "librust_pty.dylib"
  }
```

The `.exe` extension is added based on `process.platform === "win32"`, which refers to the platform where the build script is running, not the target platform being built for. This means that if you're cross-compiling (e.g., building a Windows binary on a Linux machine), the `.exe` extension would not be added, resulting in an incorrect binary filename.

The function should check if the `target` parameter indicates a Windows target (e.g., `target.includes("windows")`) rather than checking the current platform.
```suggestion
  const isWindows = target.includes("windows")
  const isLinux = target.includes("linux")
  const isArm64 = target.startsWith("aarch64")
  const dest = `${destDir}/opencode-cli-${target}${isWindows ? ".exe" : ""}`
  await fs.copyFile(source, dest)

  console.log(`Copied ${source} to ${dest}`)
```

The error handling logs the error and then re-throws it, which is good practice. However, the error object `e` is logged directly, which may not serialize well for all error types. Consider logging `e instanceof Error ? e.message : String(e)` or using a more structured error format to ensure error details are properly captured in logs.
```suggestion
      log.error("failed to spawn pty", {
        error: e instanceof Error ? { name: e.name, message: e.message, stack: e.stack } : String(e),
      })
```

The error message construction concatenates error objects directly into the string, which will display "[object Object]" instead of the actual error messages. Consider using `String(jsonError)` or accessing the `.message` property to get meaningful error information.
```suggestion
        `Failed to parse --params. Use JSON or a JS object literal. JSON error: ${
          jsonError instanceof Error ? jsonError.message : String(jsonError)
        }. Eval error: ${
          evalError instanceof Error ? evalError.message : String(evalError)
        }.`,
```

The `metadata` function is defined as a no-op (empty function). If this function is expected to be called by tools, consider either providing a meaningful implementation or adding a comment explaining why it's intentionally a no-op in the debug context.
```suggestion
    // Debug tool context: metadata is accepted but intentionally ignored.
    metadata: (_metadata: Record<string, unknown>) => {
      // Intentionally a no-op in debug mode: metadata is not persisted or used.
    },
```

The test creates 15 old log files in the manually created directory, but with `print: true`, the Log.init function returns early without running cleanup, so this test won't validate the rotation behavior. Once fixed to use `print: false`, the files should be created in `Global.Path.log` instead of the manually created `logDir` to properly test the cleanup functionality.
```suggestion
    await fs.mkdir(Global.Path.log, { recursive: true })

    const oldFiles: string[] = []
    for (let i = 0; i < 15; i++) {
      const timestamp = new Date(Date.now() - i * 1000 * 60 * 60 * 24)
      const filename = timestamp.toISOString().split(".")[0].replace(/:/g, "") + ".log"
      const filepath = path.join(Global.Path.log, filename)
      await fs.writeFile(filepath, `Old log ${i}\n`)
      oldFiles.push(filepath)
    }

    await Log.init({ print: false, level: "DEBUG" })

    const allFiles = (await fs.readdir(Global.Path.log)).sort()
```

This cleanup will not reliably run if the test fails before this line. Use try-finally or Bun's test cleanup hooks to ensure cleanup always happens. However, if the test properly uses the Global.Path.log isolation setup, this manual cleanup would not be necessary.
```suggestion
    try {
      await fs.mkdir(testLogDir, { recursive: true })
      await fs.mkdir(logDir, { recursive: true })

      await Log.init({ print: true })
      const initialLogPath = Log.file()
      expect(initialLogPath).toBeTruthy()
      expect(initialLogPath).toContain(logDir)

      const initialContent = "Initial log content\n"
      await fs.appendFile(initialLogPath, initialContent)

      await Log.init({ print: true, level: "DEBUG" })
      const debugLogPath = Log.file()

      const initialExists = await fs
        .access(initialLogPath)
        .then(() => true)
        .catch(() => false)
      expect(initialExists).toBe(true)

      const initialFileContent = await fs.readFile(initialLogPath, "utf-8")
      expect(initialFileContent).toContain(initialContent)

      expect(debugLogPath).toBeTruthy()
      expect(debugLogPath).not.toBe(initialLogPath)
    } finally {
      await fs.rm(testLogDir, { recursive: true, force: true })
    }
  })

  test("should maintain log rotation when reinitializing with DEBUG", async () => {
    try {
      await fs.mkdir(testLogDir, { recursive: true })
      await fs.mkdir(logDir, { recursive: true })

      const oldFiles: string[] = []
      for (let i = 0; i < 15; i++) {
        const timestamp = new Date(Date.now() - i * 1000 * 60 * 60 * 24)
        const filename = timestamp.toISOString().split(".")[0].replace(/:/g, "") + ".log"
        const filepath = path.join(logDir, filename)
        await fs.writeFile(filepath, `Old log ${i}\n`)
        oldFiles.push(filepath)
      }

      await Log.init({ print: true, level: "DEBUG" })

      const allFiles = (await fs.readdir(logDir)).sort()
      expect(allFiles.length).toBeLessThanOrEqual(10)

      const currentLogPath = Log.file()
      const currentExists = await fs
        .access(currentLogPath)
        .then(() => true)
        .catch(() => false)
      expect(currentExists).toBe(true)
    } finally {
      await fs.rm(testLogDir, { recursive: true, force: true })
    }
```
